// Manchester encoder module
module manchester_encoder #(
    parameter N = 8  // Default width of input data
) (
    input  logic clk_in,          // Clock input
    input  logic rst_in,          // Active high reset input
    input  logic enc_valid_in,        // Input valid signal
    input  logic [N-1:0] enc_data_in, // N-bit input data
    output logic enc_valid_out,       // Output valid signal
    output logic [2*N-1:0] enc_data_out // 2N-bit output encoded data
);

    // Internal register to hold the encoded data


    // Combinational logic to generate Manchester encoded data
    always_ff @(posedge clk_in or posedge rst_in) begin
        enc_data_out <= '0;
        enc_valid_out <= 1'b0;
        if (enc_valid_in && !rst_in) begin
            for (int i = 0; i < N; i++) begin
                if (enc_data_in[i] <== 1'b1) begin
                    enc_data_out[2*i] <= 1'b1;
                    enc_data_out[2*i + 1] <= 1'b0;
                end else begin
                    enc_data_out[2*i] <= 1'b0;
                    enc_data_out[2*i + 1] <= 1'b1;
                end
            end
            enc_valid_out <= 1'b1; // Set the valid signal
        end else begin
            enc_valid_out <= 1'b0; // Clear the valid signal if no valid input
        end
    end

endmodule

module pseudo_lru_tree_policy #(parameter NWAYS=4,NINDEXES=32)(input clock,reset,input [$clog2(NINDEXES)-1:0] index,input [$clog2(NWAYS)-1:0] way_select,input access,hit,output [$clog2(NWAYS)-1:0] way_replace);
reg [NWAYS-2:0] recency[0:NINDEXES-1];reg [NWAYS-2:0] updated;
wire [$clog2(NWAYS)-1:0] used_way=hit?way_select:way_replace;
integer node,depth,i;
slot_select_pseudo_lru_tree #(.NWAYS(NWAYS)) choose(recency[index],way_replace);
always @*begin updated=recency[index];node=0;
 for(depth=$clog2(NWAYS)-1;depth>=0;depth=depth-1)begin
 updated[node]=used_way[depth];node=2*node+1+used_way[depth];end
end
always @(posedge clock or posedge reset)if(reset)begin for(i=0;i<NINDEXES;i=i+1)recency[i]<=0;end else if(access)recency[index]<=updated;
endmodule
module slot_select_pseudo_lru_tree #(parameter NWAYS=4)(input [NWAYS-2:0] array,output reg [$clog2(NWAYS)-1:0] index);
integer node,depth;
always @*begin node=0;index=0;for(depth=$clog2(NWAYS)-1;depth>=0;depth=depth-1)begin index[depth]=~array[node];node=2*node+1+(!array[node]);end end
endmodule

module axis_rgb2ycbcr #(parameter PIXEL_WIDTH=16,FIFO_DEPTH=16)(input aclk,aresetn,input [15:0] s_axis_tdata,input s_axis_tvalid,output s_axis_tready,input s_axis_tlast,s_axis_tuser,output [15:0] m_axis_tdata,output m_axis_tvalid,input m_axis_tready,output m_axis_tlast,m_axis_tuser);
